 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE, textureLoader, emit } = ctx;
  const { Group, Mesh, PlaneGeometry, Shape, ShapeGeometry, DoubleSide } = THREE;

  const palette = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };
  const c = {
    ink: palette.ink ?? '#16161d',
    paper: palette.paper ?? '#e8ecf2',
    accent: palette.accent ?? '#ff2a38',
    surface: palette.surface ?? '#0b0b10'
  };

  const root = new Group();
  root.name = config.id ?? config.nodeId ?? 'journal-card-3';

  const cardGroup = new Group();
  root.add(cardGroup);

  const srcW = 512;
  const srcH = 320;
  const aspect = srcW / srcH;
  const cardW = 3.0;
  const cardH = cardW / aspect;

  const cardGeo = new PlaneGeometry(cardW, cardH);
  const cardMat = new MeshBasicNodeMaterial({
    transparent: true,
    alphaTest: 0.05,
    side: DoubleSide
  });
  const card = new Mesh(cardGeo, cardMat);
  cardGroup.add(card);

  textureLoader.loadTexture(config.imageUrl)
    .then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.needsUpdate = true;
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    })
    .catch(() => {
      cardMat.color.set(c.paper);
    });

  const pad = 0.04;

  const backGeo = new PlaneGeometry(cardW + pad * 2, cardH + pad * 2);
  const backMat = new MeshBasicNodeMaterial({ color: c.ink });
  const backer = new Mesh(backGeo, backMat);
  backer.position.z = -0.05;
  cardGroup.add(backer);

  const outer = new Shape();
  const ow = cardW / 2 + pad;
  const oh = cardH / 2 + pad;
  outer.moveTo(-ow, -oh);
  outer.lineTo(ow, -oh);
  outer.lineTo(ow, oh);
  outer.lineTo(-ow, oh);
  outer.lineTo(-ow, -oh);

  const inner = new Shape();
  const iw = cardW / 2;
  const ih = cardH / 2;
  inner.moveTo(-iw, -ih);
  inner.lineTo(-iw, ih);
  inner.lineTo(iw, ih);
  inner.lineTo(iw, -ih);
  inner.lineTo(-iw, -ih);
  outer.holes.push(inner);

  const frameGeo = new ShapeGeometry(outer);
  const frameMat = new MeshBasicNodeMaterial({
    color: c.accent,
    transparent: true,
    opacity: 0
  });
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.z = 0.002;
  cardGroup.add(frame);

  const badgeRadius = 0.08;
  const badgeGeo = new THREE.CircleGeometry(badgeRadius, 32);
  const badgeMat = new MeshBasicNodeMaterial({ color: c.accent });
  const badge = new Mesh(badgeGeo, badgeMat);
  badge.position.set(
    cardW / 2 - badgeRadius - 0.08,
    cardH / 2 - badgeRadius - 0.08,
    0.006
  );
  cardGroup.add(badge);

  let inStock = true;

  const updateStock = (value) => {
    inStock = !!value;
    badgeMat.color.set(inStock ? c.accent : c.paper);
  };

  if (config.data?.inventory?.inStock !== undefined) {
    updateStock(config.data.inventory.inStock);
  } else if (config.intent?.data?.inStock !== undefined) {
    updateStock(config.intent.data.inStock);
  } else {
    updateStock(true);
  }

  let isHover = false;
  let isPress = false;

  const hoverTL = gsap.timeline({ paused: true })
    .to(cardGroup.position, {
      z: 0.15,
      duration: 0.5,
      ease: 'power2.out'
    });

  const pressTL = gsap.timeline({ paused: true })
    .to(cardGroup.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)'
    });

  const focusTL = gsap.timeline({ paused: true })
    .to(frameMat, {
      opacity: 1,
      duration: 0.3,
      ease: 'power2.out'
    });

  root.userData.stockBadge = badge;
  root.userData.updateStock = updateStock;

  root.userData.handlers = {
    onPointerEnter: () => {
      isHover = true;
      hoverTL.play();
      focusTL.play();
    },
    onPointerLeave: () => {
      isHover = false;
      if (!isPress) {
        hoverTL.reverse();
        focusTL.reverse();
      }
    },
    onPointerDown: () => {
      isPress = true;
      pressTL.play();
    },
    onPointerUp: () => {
      isPress = false;
      pressTL.reverse();
      if (!isHover) {
        hoverTL.reverse();
        focusTL.reverse();
      }
    },
    onFocus: () => {
      focusTL.play();
    },
    onBlur: () => {
      if (!isHover && !isPress) focusTL.reverse();
    },
    onClick: () => {
      emit('hub-journal.select', {
        cardId: root.name,
        inStock
      });
    }
  };

  root.userData.cleanup = () => {
    hoverTL.kill();
    pressTL.kill();
    focusTL.kill();

    cardGeo.dispose();
    backGeo.dispose();
    frameGeo.dispose();
    badgeGeo.dispose();

    cardMat.dispose();
    backMat.dispose();
    frameMat.dispose();
    badgeMat.dispose();

    if (cardMat.map) cardMat.map.dispose();
  };

  return root;
}
